contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        require(to != address(this));

        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool frozenCaller = c.frozenAccount(address(this)); if (__ESBMC_reverted()) return;
        bool frozenTo = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        uint256 callerBalanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBalanceAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 transferHappened = (frozenCaller || frozenTo) ? 0 : (amount > 0 ? 1 : 1);

        assert(callerBalanceAfter + toBalanceAfter == c.balanceOf(address(this)) + c.balanceOf(to));
    }

    receive() external payable {}
}

